import * as mod from "node:module";
import * as fs from "node:fs";
import * as os from "node:os";
function main(): void {
  const M: any = (mod as any).default;
  const m = new M();
  console.log(Object.keys(m).join(), JSON.stringify(m.path), m.parent, typeof m.paths, m.isPreloading);
  console.log(M.wrap("x") === M.wrapper[0] + "x" + M.wrapper[1], M.wrapper.length, typeof M.prototype.load, typeof M.prototype.require, M.globalPaths.length >= 3);
  console.log(typeof M.findPackageJSON, mod.findPackageJSON.length, mod.findSourceMap.length, mod.register.length, mod.registerHooks.length);
  const child = new M("/a/b/c.js", m);
  console.log(child.path, child.parent === m, m.children.length);
  const dir = fs.mkdtempSync(os.tmpdir() + "/r152-");
  fs.mkdirSync(dir + "/sub");
  fs.writeFileSync(dir + "/package.json", "{}");
  fs.writeFileSync(dir + "/sub/a.js", "module.exports = 1;");
  const found = M.findPackageJSON("./a.js", "file://" + dir + "/sub/x.js");
  console.log(found === dir + "/package.json");
  fs.rmSync(dir, { recursive: true });
}
